+		if (cxl_add_extent(mds, pos->extent, seq) < 0) {
+			dev_dbg(dev,
+				"Tag %pUb: failed to add extent DPA:%#llx LEN:%#llx\n",
+				tag,
+				le64_to_cpu(pos->extent->start_dpa),
+				le64_to_cpu(pos->extent->length));
+			delete_extent_node(pos);
+			continue;
+		}
+		group_cnt++;
+	}
